"use client";

import { useEffect, useState } from "react";
import tracks from "@/data/tracks.json";
import lessons from "@/data/lessons.json";
import ProgressBar from "@/components/ProgressBar";
import TrackSection from "@/components/TrackSection";
import { getProgress } from "@/lib/progress";

export default function LearnPage() {
  const [progress, setProgress] = useState({
    completed: [],
    xp: 0,
    streak: 1
  });

  useEffect(() => {
    setProgress(getProgress());
  }, []);

  const completedCount = progress.completed.length;
  const totalLessons = lessons.length;
  const percent =
    totalLessons === 0
      ? 0
      : Math.round((completedCount / totalLessons) * 100);

  return (
    <section className="page-shell stack-lg">
      <div className="section-heading">
        <div>
          <span className="eyebrow">FINLEARN CURRICULUM</span>
          <h1>Your learning path</h1>
          <p className="lead compact">
            Start with everyday money skills, then move into borrowing,
            investing, protection and behavioural finance.
          </p>
        </div>

        <div className="track-progress-box">
          <strong>{completedCount}/{totalLessons}</strong>
          <span>lessons completed</span>
        </div>
      </div>

      <ProgressBar value={percent} />

      <div className="track-list">
        {tracks.map((track) => {
          const trackLessons = lessons.filter(
            (lesson) => lesson.trackId === track.id
          );

          return (
            <TrackSection
              key={track.id}
              track={track}
              lessons={trackLessons}
              completed={progress.completed}
            />
          );
        })}
      </div>
    </section>
  );
}
